        process_evidence = _collect_trajectory_process(context)
        if process_evidence.get("available"):
            verdict["checks"].extend(process_evidence["checks"])
            if process_evidence.get("parse_errors"):
                verdict["failures"].append("trajectory.parse_errors")
            verdict["failures"].extend(check["check_id"] for check in process_evidence["checks"] if not check["passed"])
            verdict["status"] = "PASS" if not verdict["failures"] and not observed.get("errors") else "FAIL"
        verdict.update({
            "task_id": TASK_ID,
            "ruleset_sha256": RULESET_SHA256,
            "source_state_mode": "human_completed_eval_only",
            "read_only": True,
            "business_state_mutations": [],
            "step_groups": STEP_GROUPS,
            "checkpoint_specs": CHECKPOINT_SPECS,
            "automatic_process_evidence": process_evidence,
        })
        passed = verdict["status"] == "PASS"
        return EvalResult(
            status=EvalStatus.PASS if passed else EvalStatus.FAIL,
            message="QA70 original instruction exact state verified" if passed else "QA70 mismatches: " + ", ".join(verdict["failures"]),
            metadata=verdict,
        )
